uniform float speed : 0.0 .. 5.0 = 1.0;
void update() {
    vec3 center = vec3(0.0, 0.0, 0.0);
    vec2 offset = vec2(.4, .6);
    for (int i=0; i < led.count; i++) {
        Led led_i = led[i];
        float phase = fract(led_i.s - time * speed);
        float band = smoothstep(0.1, 0.0, abs(phase - 0.5));
        vec3 color = shade(led_i);
        center += vec2(color.x, color.y);
    }
    trail[led.count] = center;
}
vec3 shade(Led led) {
    return vec3(1.0, 0.0, 0.0);
}}.

uniform float speed : 0.0 .. 5.0 = 1.0;
void update() {
    vec3 shade(Led led)
    {
        vec3 color = vec3(1.0, 0.0, 0.0);
        float phase = fract(sin(time * speed));
        float band = smoothstep(0.5, 0.0, abs(phase - 0.5));
        return color * band;
    }
}

uniform float speed : 0.0 .. 5.0 = 1.0;
void update() {
    state.x += dt * speed;
} 
vec3 shade(Led led) {
    vec3 color = vec3(0.0, 0.0, 0.0);
    float phase = fract(led.s - time * speed);
    if (phase > 0.5) {
        color = mix(color, vec3(1.0, 0.0, 0.0), 0.25);
    }
    return color;
}

uniform float speed : 0.0 .. 5.0 = 1.0;
void update() {
    state.x += dt * speed;
    blend(state.x, time);
}
vec3 shade(Led led) {
    vec3 color = vec3(1.0, 0.0, 0.0);
    return color * blend(color, led.s);
}}

